--changeset beadle:004-business-service-actions dbms:oracle,h2
UPDATE BEADLE_ACTION_HISTORY SET ACTION = REPLACE(ACTION, 'DEPARTMENT_', 'BUSINESS_SERVICE_') WHERE ACTION LIKE 'DEPARTMENT%';
UPDATE BEADLE_ACTION_HISTORY SET OBJECT_TYPE = 'BUSINESS_SERVICE' WHERE OBJECT_TYPE = 'DEPARTMENT';
ALTER TABLE BEADLE_ACTION_HISTORY DROP CONSTRAINT CK_BEADLE_ACTION_HISTORY_ACTION;
