ALTER TABLE BEADLE_ACTION_HISTORY ADD CONSTRAINT CK_BEADLE_ACTION_HISTORY_ACTION CHECK (ACTION IN ('CHANGE_PREVIEWED',
    'CHANGE_RAISED', 'CHANGE_EDITED', 'CHANGE_TASKS_CREATED', 'SECURE_CODING_TICKET_CREATED', 'REMINDER_SENT',
    'CHANGE_SYNCED', 'PRODUCT_CREATED', 'PRODUCT_UPDATED', 'PRODUCT_DELETED', 'CHANGE_PROFILE_UPDATED',
    'BUSINESS_SERVICE_CREATED', 'BUSINESS_SERVICE_RENAMED', 'BUSINESS_SERVICE_DELETED', 'USER_SIGNED_IN',
    'CALLBACK_PROTECH', 'CALLBACK_INTERNAL'));
ALTER TABLE BEADLE_ACTION_HISTORY ADD CONSTRAINT CK_BEADLE_ACTION_HISTORY_OBJECT_TYPE CHECK (OBJECT_TYPE IN ('CHANGE',
    'PRODUCT', 'CHANGE_PROFILE', 'BUSINESS_SERVICE', 'TICKET', 'USER'));
